PANTHEON_EPSILON_CATEGORIES = {
    "education": {"name": "Education & Pedagogy", "agents": EDUCATION_AGENTS, "color": "#4338CA"},
    "philosophy_design": {"name": "Philosophy of Game Design", "agents": PHILOSOPHY_DESIGN_AGENTS, "color": "#7C3AED"},
    "ethics": {"name": "Ethics & Responsible Design", "agents": ETHICS_AGENTS, "color": "#DC2626"},
    "accessibility": {"name": "Accessibility & Inclusive Design", "agents": ACCESSIBILITY_AGENTS, "color": "#2563EB"},
}

def get_all_pantheon_epsilon_agents() -> list:
    agents = []
    for cat_id, cat in PANTHEON_EPSILON_CATEGORIES.items():
        for agent in cat["agents"]:
            agents.append({"id": agent["id"], "name": agent["name"], "role": agent["role"], "specialty": agent["specialty"], "color": agent["color"], "category": cat_id, "category_name": cat["name"]})
    return agents

def get_pantheon_epsilon_prompt(agent_id: str, context: str) -> tuple:
    for cat_id, cat in PANTHEON_EPSILON_CATEGORIES.items():
        for agent in cat["agents"]:
            if agent["id"] == agent_id:
                return (f"{agent['persona']}\n\nYou are part of the Expert Pantheon (Epsilon Division).", f"As {agent['name']} ({agent['role']}), apply your expertise to:\n\n{context}")
    return ("You are a domain expert.", f"Analyze: {context}")
